/*---
description: toUpperCase of every code point U+E0000 through U+EFFFF matches Node by 4096-point block.
features: [ts-unicode-case-mapping, ts-strings, ts-unicode-exhaustive, ts-arrays, ts-tuples, ts-iteration, ts-numbers]
---*/
// Generated by tooling/unicode-cases/case-mapping.ts; Unicode 17.0 / ICU 78.3.
// Contract: docs/foundations/unicode.md, Staying identical to node.
// Hash: FNV-1a, UTF-16 code units, offset 0x811c9dc5, prime 0x01000193.
// String.fromCodePoint keeps U+D800..U+DFFF as individual lone surrogate code units.
const blocks: [number, number][] = [
  [0xE0000, 0xF0E0D1C5],
  [0xE1000, 0x91C001C5],
  [0xE2000, 0x77ADE9C5],
  [0xE3000, 0xA48E59C5],
  [0xE4000, 0x4B0BF9C5],
  [0xE5000, 0xF60799C5],
  [0xE6000, 0x368D71C5],
  [0xE7000, 0x215761C5],
  [0xE8000, 0xC1D19C5],
  [0xE9000, 0x7418E1C5],
  [0xEA000, 0x6DA879C5],
  [0xEB000, 0xAAB799C5],
  [0xEC000, 0x812901C5],
  [0xED000, 0x11C729C5],
  [0xEE000, 0x8AB5A9C5],
  [0xEF000, 0xD3FA99C5],
];
for (const [start, expected] of blocks) {
  let hash = 0x811c9dc5;
  for (let cp = start; cp < start + 4096; cp++) {
    const output = String.fromCodePoint(cp).toUpperCase();
    for (let unit = 0; unit < output.length; unit++) {
      hash = Math.imul(hash ^ output.charCodeAt(unit), 0x01000193) >>> 0;
    }
  }
  assert.sameValue(hash, expected, "toUpperCase block U+" + start.toString(16) + "..U+" + (start + 4095).toString(16));
}
